 @Override public void onCreate(Bundle state){super.onCreate(state);keepModel=state==null?getIntent().getBooleanExtra("keep_model",false):state.getBoolean("keepModel",false);group=VoiceNavigation.group(getIntent());demoId=getIntent().getStringExtra("demo_id");if(demoId==null)demoId="";if(state!=null){group=state.getString("group",group);demoId=state.getString("demoId",demoId);String s=state.getString("input");if(s!=null)input=Uri.parse(s);}else input=VoiceNavigation.input(getIntent());if(keepModel)group="ALL";startGate=new VoiceComparisonPolicy.StartGate(getIntent().getBooleanExtra("auto_start",false),state!=null,input!=null);build();if(state!=null){ArrayList<String> ids=state.getStringArrayList("selectedModels");if(ids!=null)for(Map.Entry<String,CheckBox> item:checks.entrySet())item.getValue().setChecked(ids.contains(item.getKey()));try{rows=new JSONArray(state.getString("rows","[]"));}catch(JSONException ignored){}showRows(rows);interrupted=state.getBoolean("wasRunning",false);status.setText(interrupted?"이전 비교가 중단됐습니다 · 선택 모델로 다시 시작하세요":state.getString("status",status.getText().toString()));restorePosition(state.getFloat("scrollFraction",0));buttons();}}
